func RankEntries(entries []dossiers.Entry, targetAnchors []string) []RankedEntry {
	var ranked []RankedEntry

	targetSet := make(map[string]bool)
	for _, a := range targetAnchors {
		targetSet[a] = true
	}

	for _, e := range entries {
		score := 0
		anchorMatch := ""

		// 1. Anchor match
		if len(e.Anchors) == 0 {
			score += 100
			anchorMatch = "scope"
		} else {
			matchedExact := false
			// We simplify directory vs exact here. For now, assume if it matches target, it's exact.
			// The specification:
			// - Exact file/symbol match: +1000
			// - Directory match: +500
			// - Scope-only: +100
			// Wait, the specification implies we might pass target directories or the entry has directory anchors?
			// Let's implement basic matching for exact. We can check if any anchor is in targetSet.
			for _, a := range e.Anchors {
				if targetSet[a] {
					matchedExact = true
					break
				}
			}
			if matchedExact {
				score += 1000
				anchorMatch = "exact"
			} else {
				// We don't have enough context to distinguish directory match here unless we do prefix matching.
				// For now, if no target anchors matched, it's not exact.
				// Wait, let's add logic for directory match: target startswith anchor + "/"
				matchedDir := false
				for _, ta := range targetAnchors {
					for _, a := range e.Anchors {
						if len(ta) > len(a) && ta[:len(a)] == a && (ta[len(a)] == '/' || a[len(a)-1] == '/') {
							matchedDir = true
							break
						}
					}
					if matchedDir {
						break
					}
				}
				if matchedDir {
					score += 500
					anchorMatch = "directory"
				}
			}
		}

		// 2. Entry type
		score += typeOrderRanking[e.Type]

		// 3. Verification status
		if e.Verified != "" {
			score += 200
		}

		// 4. Evidence count
		evScore := len(e.Evidence) * 10
		if evScore > 50 {
			evScore = 50
		}
		score += evScore

		ranked = append(ranked, RankedEntry{
			Entry:       e,
			Score:       score,
			AnchorMatch: anchorMatch,
		})
	}

	sort.Slice(ranked, func(i, j int) bool {
		return ranked[i].Score > ranked[j].Score
	})

	return ranked
}

func SelectWithinBudget(ranked []RankedEntry, tokenBudget int) []RankedEntry {
	var selected []RankedEntry
	usedTokens := 0

	for _, r := range ranked {
		tokens := len(r.Entry.Text) / 4
		if tokens == 0 {
			tokens = 1
		}
		if usedTokens+tokens <= tokenBudget {
			selected = append(selected, r)
			usedTokens += tokens
		}
	}

	return selected
}
