				anchorMatch = "exact"
			} else {
				matchedDir := false
				for _, ta := range targetAnchors {
					for _, a := range e.Anchors {
						if len(ta) > len(a) && ta[:len(a)] == a && (ta[len(a)] == '/' || a[len(a)-1] == '/') {
							matchedDir = true
							break
						}
					}
					if matchedDir {
						break
					}
				}
				if matchedDir {
					score += 500
					anchorMatch = "directory"
				}
			}
		}

		// 2. Entry type
		score += typeOrderRanking[e.Type]

		// 3. Verification status
		if e.Verified != "" {
			score += 200
		}

		// 4. Evidence count
		evScore := len(e.Evidence) * 10
		if evScore > 50 {
			evScore = 50
		}
		score += evScore

		ranked = append(ranked, RankedEntry{
			Entry:       e,
			Score:       score,
			AnchorMatch: anchorMatch,
		})
	}

	sort.Slice(ranked, func(i, j int) bool {
		return ranked[i].Score > ranked[j].Score
	})

	return ranked
}

func SelectWithinBudget(ranked []RankedEntry, tokenBudget int) []RankedEntry {
	var selected []RankedEntry
	usedTokens := 0

	for _, r := range ranked {
		tokens := len(r.Entry.Text) / 4
		if tokens == 0 {
			tokens = 1
		}
		if usedTokens+tokens <= tokenBudget {
			selected = append(selected, r)
			usedTokens += tokens
		}
	}

	return selected
}

package delivery

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
)

func FormatEntry(entry dossiers.Entry) string {
	return fmt.Sprintf("[repo-memory %s] %s: %s", entry.ID, entry.Type, entry.Text)
}

func FormatEntries(entries []RankedEntry) string {
	if len(entries) == 0 {
		return ""
	}
	var sb strings.Builder
	sb.WriteString("--- repo-memory context ---\n")
	for _, r := range entries {
		sb.WriteString(FormatEntry(r.Entry))
		sb.WriteString("\n")
	}
	sb.WriteString("---")
	return sb.String()
}

func FormatGateDeny(entry dossiers.Entry) string {
	return fmt.Sprintf("[REPO-MEMORY %s] %s. Re-issue the edit after checking this.", entry.ID, entry.Text)
}

func ContentHash(text string) string {
	hash := sha256.Sum256([]byte(text))
	return hex.EncodeToString(hash[:])
}

